# Epilogue for CR-001
# Defensive checks and conditional exports
out_dir <- "/work/out"
if (!dir.exists(out_dir)) dir.create(out_dir, recursive = TRUE)

# Helper to write CSV only if object exists
write_if_exists <- function(obj_name, write_fun) {
  if (exists(obj_name, inherits = FALSE)) {
    obj <- get(obj_name, inherits = FALSE)
    write_fun(obj)
  }
}

# 1. frame.csv – raw input rows used for scoring (sc)
if (exists("sc", inherits = FALSE)) {
  frame <- sc
  frame$.row <- seq_len(nrow(frame))
  write.csv(frame, file.file.path(out_dir, "frame.csv"), row.names = FALSE)
} else {
  warning("Object 'sc' not found – frame.csv will not be created")
}

# 2. scores.csv – model output (pd) and decision if available
if (exists("pd", inherits = FALSE)) {
  scores <- data.frame(.row = seq_len(length(pd)), score = pd, stringsAsFactors = FALSE)
  if (exists("decision", inherits = FALSE)) {
    scores$decision <- get("decision", inherits = FALSE)
  }
  write.csv(scores, file = file.path(out_dir, "scores.csv"), row.names = FALSE)
} else {
  warning("Object 'pd' not found – scores.csv will not be created")
}

# 3. coef.csv – coefficients if cf exists (legacy script also writes cf)
if (exists("cf", inherits = FALSE)) {
  coef_df <- data.frame(term = names(cf), estimate = unname(cf), stringsAsFactors = FALSE)
  write.csv(coef_df, file = file.path(out_dir, "coef.csv"), row.names = FALSE)
} else if (exists("fit", inherits = FALSE)) {
  # fallback to coef(fit) if cf missing
  cf2 <- coef(fit)
  coef_df <- data.frame(term = names(cf2), estimate = unname(cf2), stringsAsFactors = FALSE)
  write.csv(coef_df, file = file.path(out_dir, "coef.csv"), row.names = FALSE)
} else {
  warning("Neither 'cf' nor 'fit' found – coef.csv will not be created")
}

# 4. train_rows.csv – include if training subset information is present (e.g., object 'train_rows')
if (exists("train_rows", inherits = FALSE)) {
  tr <- data.frame(.row = get("train_rows", inherits = FALSE))
  write.csv(tr, file = file.path(out_dir, "train_rows.csv"), row.names = FALSE)
}

# 5. Bundle all relevant objects into a single RDS for downstream use
# Collect objects that are likely useful – we include any that exist among a whitelist
bundle_objs <- c("sc", "Xs", "pd", "decision", "cf", "fit", "X", "X s", "woe_tabs", "b", "dat", "args", "outdir")
export_bundle <- list(model_name = "CR-001 Retail PD Scorecard", bundle_path = out_dir)
for (nm in bundle_objs) {
  if (exists(nm, inherits = FALSE)) {
    export_bundle[[nm]] <- get(nm, inherits = FALSE)
  }
}
saveRDS(export_bundle, file = file.path(out_dir, "export_bundle.rds"))

# End with explicit success status
quit(status = 0)
